  ('ca36a377-5293-51b5-b8b2-8f9d0b047aa1', null, (select id from public.skills where slug = 'write-g9-writing-with-evidence'), null, 'medium',
   $q$Which sentence would best fill the blank in sentence 5 by supporting the claim that the students benefit too?$q$, $q$[{"text":"Lindqvist reports that the students' English teacher saw their essays grow longer and more detailed during the program.","is_correct":true},{"text":"Many teenagers today send dozens of text messages to their friends every single day.","is_correct":false,"misconception_token":"general-fact-not-text"},{"text":"Lindqvist believes every school in the country should start a pen pal program right away.","is_correct":false,"misconception_token":"opinion-not-evidence"},{"text":"Residents at the center also enjoy weekly music nights and craft afternoons in the main hall.","is_correct":false,"misconception_token":"irrelevant-detail"}]$q$::jsonb, $q$Lindqvist reports that the students' English teacher saw their essays grow longer and more detailed during the program.$q$, $q$Sentence 4 covers the residents, so sentence 5 needs evidence that students gain something, and better essays show that. The music nights detail is about the center, not about the students or the letters.$q$, 'draft', '0f289b91-dfa0-52ae-ad8d-faf331dc736f')
